use crate::{crypto::Identity, error::{LocalDropError, Result}, http::{headers, LocalHttp}, protocol::{create_manifest, prepare_file, read_chunk, ManifestFile, Remote}};
use std::{fs::File, path::PathBuf};
use uuid::Uuid;
const CHUNK_SIZE: usize=1024*1024;

pub fn send(http:&LocalHttp,remote:&Remote,identity:&Identity,device:&str,paths:&[PathBuf])->Result<()> { if paths.is_empty(){return Err(LocalDropError::Usage);} let files:Vec<ManifestFile>=paths.iter().map(|p|prepare_file(p)).collect::<Result<_>>()?;let manifest=create_manifest(&files)?;let session=Uuid::new_v4().to_string();let total:u64=files.iter().map(|f|f.size).sum();
 for (index,file) in files.iter().enumerate(){let mut input=File::open(&file.path)?;let mut offset=0u64;while offset<file.size||file.size==0{let length=if file.size==0{0}else{std::cmp::min(CHUNK_SIZE as u64,file.size-offset) as usize};let body=read_chunk(&mut input,offset,length)?;if body.len()!=length{return Err(LocalDropError::Io(std::io::Error::new(std::io::ErrorKind::UnexpectedEof,"archivo cambió durante la lectura")));}let h=headers(remote,identity,&session,&manifest,index,offset,file.size,device)?;let next=http.chunk(remote,h,body)?.unwrap_or(offset+length as u64);if next<=offset||next>file.size||(file.size==0&&next!=0){return Err(LocalDropError::Offset(format!("{next} fuera de {}..{}",offset,file.size)));}offset=next;let done=files[..index].iter().map(|f|f.size).sum::<u64>()+offset;println!("Enviando {}: {}/{} bytes (total {}/{})",file.path.display(),offset,file.size,done,total);if file.size==0{break;}}println!("Enviado: {}",file.path.display());}Ok(()) }
